log_softmax_max_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void log_softmax_max_kernel(const float* x, float* max_vals, int batch_size, int dim) {
    int row = blockIdx.x;
    if (row >= batch_size) return;

    extern __shared__ float sdata[];
    unsigned int tid = threadIdx.x;
    unsigned int stride = dim + tid;

    if (tid < dim) {
        sdata[tid] = x[row * dim + tid];
    } else {
        sdata[tid] = -INFINITY;
    }
    __syncthreads();

    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s && sdata[threadIdx.x + s] > sdata[threadIdx.x]) {
            sdata[threadIdx.x] = sdata[threadIdx.x + s];
        }
        __syncthreads();
    }
    if (tid == 0) {
        max_vals[row] = sdata[0];
    }
}

torch::Tensor log_softmax_max_cuda(torch::Tensor x) {
    auto batch_size = x.size(0);
    auto dim = x.size(1);
    auto total_elements = batch_size * dim;

    auto max_vals = torch::empty(batch_size, dtype=torch.float32, device=x.device);

    const int block_size = 256;
    const int num_blocks = (batch_size + block_size - 1) / block_size;

    log_softmax_max_kernel<<<num_blocks, block_size, block_size * sizeof(float)>>>(
        x.data_ptr<float()>,
        max_vals.data_ptr<float()>,
        batch_size,
        dim
    );

    return max_vals
}
"""

