log_softmax_exp_sum_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void log_softmax_exp_sum_kernel(const float* x, const float* max_vals, float* sum_exp, int batch_size, int dim) {
    int row = blockIdx.x;
    if (row >= batch_size) return;

    extern __shared__ float sdata[];
    unsigned int tid = threadIdx.x;
    unsigned int stride = dim + tid;

    if (tid < dim) {
        float val = x[row * dim + tid];
        float diff = val - max_vals[row];
        float exp_diff = expf(diff);
        sdata[tid] = exp_diff;
    } else {
        sdata[tid] = 0.0f;
    }
    __syncthreads();

    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s && sdata[threadIdx.x + s] != 0.0f) {
            sdata[threadIdx.x] += sdata[threadIdx.x + s];
        }
        __syncthreads();
    }
    if (tid == 0) {
        sum_exp[row] = sdata[0];
    }
}

torch::Tensor log_softmax_exp_sum_cuda(torch::Tensor x, torch::Tensor max_vals) {
    auto batch_size = x.size(0);
    auto dim = x.size(1);
    auto total_elements = batch_size * dim;

    auto sum_exp = torch::empty(batch_size, dtype=torch.float32, device=x.device);

    const int block_size = 256;
    const int num_blocks = (batch_size + block_size - 1) / block_size;

    log_softmax_exp_sum_kernel<<<num_blocks, block_size, block_size * sizeof(float)>>>(
        x.data_ptr<float()>,
        max_vals.data_ptr<float()>,
        sum_exp.data_ptr<float()>,
        batch_size,
        dim
    );

    return sum_exp
}
"""

