log_softmax_final_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void log_softmax_final_kernel(const float* x, const float* max_vals, const float* sum_exp, float* out, int batch_size, int dim) {
    int row = blockIdx.x;
    if (row >= batch_size) return;

    extern __shared__ float sdata[];
    unsigned int tid = threadIdx.x;
    unsigned int stride = dim + tid;

    if (tid < dim) {
        float diff = x[row * dim + tid] - max_vals[row];
        float log_sum = logf(sum_exp[row]);
        out[row * dim + tid] = diff - log_sum;
    } else {
        out[row * dim + tid] = 0.0f;
    }
    __syncthreads();
}

torch::Tensor log_softmax_cuda(torch::Tensor x) {
    auto batch_size = x.size(0);
    auto dim = x.size(1);
    auto total_elements = batch_size * dim;

    // Step 1: max per row
    auto max_vals = torch::empty(batch_size, dtype=torch.float32, device=x.device);
    const int block_size = 256;
    const int num_blocks = (batch_size + block_size - 1) / block_size;
    log_softmax_max_kernel<<<num_blocks, block_size, block_size * sizeof(float)>>>(
        x.data_ptr<float()>,
        max_vals.data_ptr<float()>,
        batch_size,
        dim
    );

    // Step 2: exp(x - max) and sum per row
    auto sum_exp = torch::empty(batch_size, dtype=torch.float32, device=x.device);
    const int block_size2 = 256;
    const int num_blocks2 = (batch_size + block_size2 - 1) / block_size2;
    log_softmax_exp_sum_kernel<<<num_blocks2, block_size2, block_size2 * sizeof(float)>>>(
        x.data_ptr<float()>,
        max_vals.data_ptr<float()>,
        sum_exp.data_ptr<float()>,
        batch_size,
        dim
    );

    // Step 3: finalize
    auto out = torch::empty_like(x);
    const int block_size3 = 256;
    const int num_blocks3 = (batch_size + block_size3 - 1) / block_size3;
    log_softmax_final_kernel<<<num_blocks3, block_size3, block_size3 * sizeof(float)>>>(
        x.data_ptr<float()>,
        max_vals.data_ptr<float()>,
        sum_exp.data_ptr<float()>,
        out.data_ptr<float()>,
        batch_size,
        dim
    );

    return out;
}
